insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',31,'Contabilidade Geral',null,'João trabalha na Cia X. Seu salário mensal, que é pago no último dia do mês trabalhado, é de R$15.000. Em janeiro de X0, João obteve um adiantamento de R$5.000 com a empresa, para ser descontado do salário de março. Assinale a opção que indica os lançamentos contábeis realizados em 31/03/X0:','{"A": "D- Despesa de salários R$10.000 C- Disponibilidades R$10.000", "B": "D- Despesa de saláriosR$15.000 C- Disponibilidades R$15.000", "C": "D- Despesa de salários R$10.000 D- Adiantamento a empregados R$5.000 C- Disponibilidades R$15.000", "D": "D- Despesa de salários R$15.000 C- Disponibilidades R$10.000 C- Despesa a pagar R$5.000", "E": "D- Despesa de salários R$15.000 C- Disponibilidades R$10.000 C- Adiantamentos a empregados R$5.000"}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',32,'Contabilidade Geral',null,'As despesas com propaganda podem ser contabilizadas, na Demonstração do Resultado do Exercício, como despesas de venda ou como despesas administrativas. Em relação à diferenciação na contabilização, assinale a afirmativa correta.','{"A": "Quando a propaganda é de um produto, será despesa de venda, quando diz respeito a vários produtos, será despesa administrativa.", "B": "Quando a propaganda é vinculada a um exercício social, será despesa de venda, quando a mais de um exercício, será despesa administrativa.", "C": "Quando a propaganda é direcionada a um meio de comunicação, será despesa de venda, quando a vários meios digitais , será despesa administrativa.", "D": "Quando a propaganda é vinculada à promoção de vendas de produtos será despesa de venda, quando representa propaganda institucional, será despesa administrativa.", "E": "Quando a propaganda é realizada após do lançamento do produto, será despesa de venda , quando é realizada antes do lançamento do produto, é despesa administrativa."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',33,'Contabilidade Geral',null,'Na constituição de uma empresa, foi definido que o capital autorizado seria de R$800.000. Deste, foram subscritos R$650.000. Em 31/12/X0, o capital a integralizar era de R$80.000. Assinale a opção que indica o capital social realizado da empresa em 31/12/X0:','{"A": "R$150.000", "B": "R$570.000", "C": "R$650.000", "D": "R$720.000", "E": "R$800.000"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',34,'Contabilidade Geral',null,'Em 01/01/X0, uma sociedade empresária adquiriu, por R$200.000 à vista, uma máquina para utilizar em seus negócios. O frete da máquina foi de R$1.000 e a sua instalação de R$4.000. Na data, foi estimado que a máquina poderia produzir 20.000 unidades do produto “abc”, sendo a produção estimada do seguinte modo: A sociedade empresária inicialmente depreciava os seus ativos imobilizados pelo método dos benefícios gerados. Em 01/01/X3, os contadores da sociedade empresária julgaram que seria mais adequado depreciar os seus ativos imobilizados de acordo com o método da linha reta. Na data, foi estimado que a máquina poderia ser utilizada por mais 5 anos a partir desta data, sendo o valor residual zero. Assinale a opção que indica a depreciação acumulada da máquina em 31/12/X4.','{"A": "R$164.000.", "B": "R$166.100.", "C": "R$168.100.", "D": "R$190.000.", "E": "R$194.750. Ano Produção X0 2.000 X1 4.000 X2 8.000 X3 3.000 X4 2.000 X5 1.000"}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',35,'Contabilidade Geral',null,'De acordo com a Lei nº 6.404/1976 e modificações, o saldo das reservas de lucros, exceto as para contingências, de incentivos fiscais e de lucros a realizar, não poderá ultrapassar o capital social. Atingindo esse limite, a assembleia deverá deliberar sobre a aplicação do excesso. A aplicação poderá ser feita','{"A": "na liquidação de passivos ou na compra de ativos.", "B": "no aumento do capital social ou na compra de ações em tesouraria.", "C": "na constituição de reservas de lucros para expansão ou na compra de ações em tesouraria.", "D": "na constituição de reservas de lucros para expansão ou na distribuição de dividendos.", "E": "no aumento do capital social ou na distribuição de dividendos."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',36,'Contabilidade Geral',null,'Em 01/01/X0, uma editora brasileira adquiriu os direitos autorais de uma coleção de livros franceses por R$300.000. O contrato tinha vigência de 5 anos a partir de 01/07/X0, quando o primeiro livro ficou pronto para ser lançado. A editora contratou um profissional para traduzir o primeiro livro; ele recebeu R$30.000 pelo serviço. Além disso, a editora organizou uma festa de lançamento do livro, na qual foram gastos R$20.000. A editora amortiza os seus contratos de direitos autorais de acordo com o método da linha reta. Assinale a opção que indica a despesa de amortização dos direitos autorais do livro em 31/12/X0.','{"A": "R$30.000.", "B": "R$33.000.", "C": "R$60.000.", "D": "R$66.000.", "E": "R$70.000."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',37,'Contabilidade Geral',null,'A Cia. Azul possui 85% de participação na Cia. Branca, contabilizando o investimento pelo método da equivalência patrimonial. Em 31/12/X0, a Cia. Branca distribuiu à Cia Azul dividendos no valor de R$40.000. Assinale a opção que indica a contabilização dos dividendos recebidos nas demonstrações contábeis da Cia. Azul em 31/12/X0, em contrapartida ao aumento de caixa.','{"A": "Aumento no Passivo.", "B": "Redução em Investimentos.", "C": "Aumento em Investimentos.", "D": "Aumento em Patrimônio Líquido.", "E": "Redução no Patrimônio Líquido."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',38,'Contabilidade Geral',null,'Com o intuito de aumentar o seu saldo em caixa, uma sociedade empresária emitiu, em 01/01/X0, ações, captando R$150.000 e debêntures, captando R$80.000. Assinale a opção que indica a contabilização do aumento em caixa e equivalentes de caixa, ocasionado pelas duas emissões, na Demonstração dos Fluxos de Caixa da sociedade empresária no ano de X0.','{"A": "Fluxo de caixa gerado pela atividade operacional: R$230.000.", "B": "Fluxo gerado pela atividade de investimentos: R$230.000.", "C": "Fluxo de caixa gerado pela atividade de financiamento: R$230.000.", "D": "Fluxo de caixa gerado pela atividade de investimento: R$150.000 e pela atividade operacional: R$80.000.", "E": "Fluxo de caixa gerado pela atividade de financiamento: R$150.000 e pela atividade de investimento: R$80.000."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',39,'Contabilidade Geral',null,'Uma entidade possui contas bancárias em três diferentes instituições. Em 31/12/X0, os saldos eram os seguintes: Assinale a opção que indica a contabilização da conta no banco Gama no balanço patrimonial da entidade.','{"A": "Passivo circulante.", "B": "Ativo circulante.", "C": "Redutora do ativo circulante.", "D": "Ativo realizável a longo prazo.", "E": "Redutora do ativo realizável a longo prazo. Banco Saldo da conta Alfa R$ 20.000 Beta R$ 18.000 Gama -R$ 10.000"}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',40,'Contabilidade Geral',null,'Em 31/12/X0, as Cias X e Y apresentavam os seguintes balanços patrimoniais: Em 01/01/X1, a Cia X adquiriu 100% de participação na Cia Y por R$35.000 à vista. Na data, a empresa estimou, em relação aos ativos e passivos da Cia Y, que:  O terreno tinha valor justo de R$23.000  A marca tinha valor justo de R$8.000  Os financiamentos tinham valor de mercado de R$10.000. Em relação ao balanço patrimonial consolidado após a aquisição, analise as afirmativas a seguir: I. O ativo circulante é de R$120.000. II. O ativo imobilizado é de R$23.000. III. O ativo intangível é de R$8.000. IV. O passivo não circulante é de R$10.000 V. O patrimônio líquido é de R$102.000. Está correto o que se afirma em','{"A": "I, III e IV, apenas.", "B": "II, IV e V, apenas.", "C": "II, III e IV, apenas.", "D": "I, II, IV e V, apenas.", "E": "II, III, IV e V, apenas."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',41,'Contabilidade Geral',null,'De acordo com a Lei nº 6.404/1976 e modificações, as operações de incorporação, fusão e cisão serão submetidas à deliberação da assembleia-geral das companhias interessadas mediante explicação, na qual serão expostos os pontos a seguir, à exceção de um. Assinale-o.','{"A": "O efeito estimado nas cotações futuras das ações na bolsa de valores.", "B": "Os motivos ou fins da operação e o interesse da companhia na sua realização.", "C": "O valor de reembolso das ações a que terão direito os acionistas dissidentes.", "D": "As ações que os acionistas preferenciais receberão e as razões para a modificação dos seus direitos, se prevista.", "E": "A composição, após a operação, segundo espécies e classes das ações, do capital das companhias que deverão emitir ações em substituição às que se deverão extinguir."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',42,'Contabilidade Geral',null,'A incorporação, fusão ou cisão da companhia emissora de debêntures em circulação dependerá da prévia aprovação dos debenturistas, reunidos em assembleia especialmente convocada com esse fim. Se for assegurado aos debenturistas que o desejarem, durante o prazo mínimo de 6 meses a contar da data da publicação das atas das assembleias relativas à operação, o resgate das debêntures de que forem titulares','{"A": "a aprovação pela assembleia será dispensada.", "B": "a incorporação, fusão ou cisão será antecipada.", "C": "uma auditoria de caráter especial será realizada.", "D": "uma demonstração financeira intermediária deverá ser publicada.", "E": "a avaliação da debênture será baseada na forma, em detrimento à essência."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',43,'Contabilidade Pública',null,'De acordo com a Lei nº 4.320/64, as receitas podem ser classificadas em correntes e de capital. Assinale a opção que contém exemplos de receita classificadas, respectivamente, como corrente e como de capital.','{"A": "Tributária e industrial.", "B": "Industrial e de serviços.", "C": "De serviços e tributária.", "D": "Patrimonial e alienação de bens.", "E": "Amortização de empréstimos e agropecuária."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',44,'Contabilidade Pública',null,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP), as características qualitativas são atributos que tornam a informação útil para os usuários e dão suporte ao cumprimento dos objetivos da informação contábil. Em relação às características qualitativas, assinale a afirmativa correta.','{"A": "A representação fidedigna é a qualidade da informação que permite que os usuários compreendam o seu significado.", "B": "A comparabilidade é a qualidade da informação que possibilita aos usuários identificar semelhanças e diferenças entre dois conjuntos de fenômenos.", "C": "A tempestividade é a qualidade da informação que influencia significativamente o cumprimento dos objetivos da elaboração e da divulgação da informação contábil.", "D": "A relevância é a qualidade da informação que aprimora a sua utilidade como insumo para processos de avaliação da prestação de contas e responsabilização e a sua capacidade de informar os processos decisórios.", "E": "A compreensibilidade é a qualidade da informação que ajuda a assegurar aos usuários que a informação contida nas demonstrações contábeis representa fielmente os fenômenos econômicos ou de outra natureza que se propõe a representar. Cia X Cia Y Ativo Circulante Disponibilidades 80.000 10.000 Estoques 30.000 Ativo não Circulante Imobilizado Terrenos 20.000 Total do Ativo 110.000 30.000 Passivo Circulante Salários a pagar 8.000 Passivo não Circulante Financiamentos 12.000 Patrimônio Líquido Capital Social 102.000 18.000 Passivo + PL 110.000 30.000"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',45,'Direito Administrativo',null,'O leilão representa uma modalidade de licitação. Ele será precedido da divulgação do edital em sítio eletrônico oficial, que conterá os aspectos a seguir, à exceção de um. Assinale-o.','{"A": "A indicação do lugar onde estão os móveis, os veículos e os semoventes.", "B": "A especificação de eventuais ônus, gravames ou pendências existentes sobre os bens a serem leiloados.", "C": "A denominação dos antigos proprietários dos bens e o motivo pelo qual os mesmos estão sendo leiloados.", "D": "A descrição do bem, com suas características, e, no caso de imóvel, sua situação e suas divisas, com remissão à matrícula e aos registros.", "E": "O valor pelo qual o bem foi avaliado, o preço mínimo pelo qual poderá ser alienado, as condições de pagamento e, se for o caso, a comissão do leiloeiro designado."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',46,'Contabilidade de Custos',null,'Em relação à diferenciação entre os custos e as despesas em uma empresa industrial, assinale a afirmativa correta.','{"A": "Os custos representam gastos, enquanto as despesas são desembolsos.", "B": "Os custos representam o evento econômico, enquanto as despesas o evento financeiro.", "C": "Os custos são considerados investimentos, enquanto as despesas são consideradas perdas.", "D": "Os custos relacionam-se ao processo produtivo, enquanto as despesas estão principalmente relacionadas com as áreas comercial e administrativa.", "E": "Os custos são contabilizados de acordo com ao regime de competência, enquanto as despesas com o regime de caixa."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',47,'Contabilidade de Custos',null,'Uma entidade utiliza o custeio por absorção. A entidade incorre nos seguintes custos e despesas em seu processo operacional: custos diretos, custos indiretos e despesas de vendas. De acordo com o método do custeio por absorção, são alocados aos produtos','{"A": "os custos diretos, apenas.", "B": "os custos indiretos, apenas.", "C": "os custos diretos e indiretos, apenas.", "D": "os custos diretos e as despesas de vendas, apenas.", "E": "os custos diretos, os custos indiretos e as despesas de vendas."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',48,'Auditoria',null,'De acordo com a NBC TI 01 – Da Auditoria Interna, o processo de obtenção e avaliação das informações compreende a obtenção de informações sobre os assuntos relacionados aos objetivos e ao alcance da Auditoria Interna. Nesse sentido, a informação adequada é aquela que, sendo confiável,','{"A": "é factual, convincente e suficiente.", "B": "auxilia a entidade a atingir suas metas, no menor espaço de tempo possível.", "C": "fornece suporte às conclusões e às recomendações da Auditoria Interna.", "D": "torna possível que uma pessoa prudente e informada tire conclusões da mesma forma como o auditor interno.", "E": "propicia a melhor evidência alcançável, por meio do uso apropriado das técnicas de Auditoria Interna."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',49,'Auditoria',null,'De acordo com a NBC TA 200 (R1) – Objetivos Gerais do Auditor Independente e a Condução da Auditoria em Conformidade com Normas de Auditoria, quando o trabalho de auditoria é de interesse público e, portanto, exigido pelo Código de Ética Profissional do Contabilista e pelas normas profissionais do CFC, exige-se que o auditor seja independente da entidade sujeita a auditoria. A independência do auditor frente à entidade caracteriza-se principalmente por','{"A": "tornar os resultados do trabalho do auditor mais ágeis e objetivos.", "B": "possibilitar que o auditor detecte ocorrências de fraude e de erro com mais precisão.", "C": "aprimorar a capacidade do auditor de atuar com maior rigor, consistência e transparência.", "D": "salvaguardar a capacidade do auditor de formar opinião de auditoria sem ser afetado por influências que poderiam comprometer essa opinião.", "E": "proporcionar um relatório do auditor mais próximo da realidade, onde a essência econômica é levada em consideração, em detrimento à forma jurídica."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',50,'Auditoria',null,'De acordo com a NBC TA 300 (R1) – Planejamento da Auditoria de Demonstrações Contábeis, o planejamento da auditoria envolve a definição de estratégia global para o trabalho e o desenvolvimento de plano de auditoria. A responsabilidade sobre o plano de auditoria é','{"A": "da administração da entidade, que deve explicar os elementos do planejamento ao auditor, de forma a melhorar a qualidade dos resultados obtidos.", "B": "do auditor e da administração da entidade que, no entanto, devem evitar discutir os elementos do planejamento, de modo a não comprometer a independência.", "C": "do auditor e da administração da entidade, que devem discutir os elementos do planejamento, de forma a melhorar a qualidade dos resultados obtidos.", "D": "do auditor, que deve abster-se de discutir os elementos do planejamento com a administração da entidade, de modo a não comprometer a eficácia dessa auditoria.", "E": "do auditor, que pode optar por discutir os elementos do planejamento com a administração da entidade, de forma a facilitar a condução e o gerenciamento do trabalho de auditoria."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',51,'Contabilidade Geral',null,'Um marco para a evolução da Contabilidade foi o processo de convergência das normas contábeis às normas internacionais. Em relação às consequências ao processo de convergência das normas contábeis, avalie se as afirmativas a seguir são falsas (F) ou verdadeiras (V): ( ) Aumento do custo do capital que deriva da processo. ( ) Redução de riscos nos investimentos internacionais, sob a forma de empréstimo financeiro ou sob a forma de participação societária. ( ) Maior facilidade de comunicação internacional no mundo dos negócios com o uso de uma linguagem contábil mais homogênea. As afirmativas são, respectivamente,','{"A": "V – V – V.", "B": "V – V – F.", "C": "V – F – V.", "D": "F – V – V.", "E": "F – F – V."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',52,'Contabilidade Geral',null,'De acordo com a NBC TG Estrutura Conceitual- Estrutura Conceitual para Relatório Financeiro, os investidores, credores por empréstimos e outros credores, existentes e potenciais, representam os principais usuários aos quais se destinam os relatórios financeiros para fins gerais. De acordo com a norma, a administração da entidade que reporta não é considerada usuário primário, uma vez que','{"A": "pode obter internamente as informações financeiras de que precisa.", "B": "é a responsável direta pela elaboração destes relatórios financeiros.", "C": "tem necessidades de informação diferentes e possivelmente conflitantes em relação aos demais usuários.", "D": "sua necessidade é mais restrita e específica, enquanto os relatórios financeiros são mais abrangentes.", "E": "trabalha com representações exatas, enquanto os relatórios financeiros baseiam-se em estimativas, julgamentos e modelos."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',53,'Contabilidade Geral',null,'De acordo com a NBC TG Estrutura Conceitual- Estrutura Conceitual para Relatório Financeiro, ativo é um direito que tem o potencial de produzir benefícios econômicos, presente e controlado pela entidade, como resultado de eventos passados. As opções a seguir indicam exemplos de direitos que representam ativos reconhecidos pela Contabilidade e que correspondem à obrigação de outra parte, à exceção de uma. Assinale-a.','{"A": "Direitos de receber caixa.", "B": "Direitos de receber produtos ou serviços.", "C": "Direitos de influenciar a tomada de decisões estratégicas.", "D": "Direitos de trocar recursos econômicos com outra parte em condições favoráveis.", "E": "Direitos de beneficiar-se de obrigação de outra parte para transferir um recurso econômico se ocorrer evento futuro incerto especificado."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',54,'Ética Profissional',null,'De acordo com o Decreto-Lei nº 9.295/46, representam atribuições do Conselho Federal de Contabilidade','{"A": "expedir e registrar a carteira profissional do profissional contabilista.", "B": "regular acerca dos princípios contábeis, do Exame de Suficiência, do cadastro de qualificação técnica e dos programas de educação continuada.", "C": "estudar, preparar e emitir, de modo exclusivo, os pronunciamentos técnicos sobre procedimentos de Contabilidade, visando à centralização e uniformização do seu processo de produção.", "D": "examinar reclamações a representações escritas acerca dos serviços de registro e das infrações dos dispositivos legais vigentes, relativos ao exercício da profissão de contabilista.", "E": "fiscalizar o exercício das profissões de contador, impedindo e punindo as infrações, e enviando às autoridades competentes relatórios sobre fatos que apurarem, e cuja solução ou repressão não seja de sua aIçada."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',55,'Ética Profissional',null,'De acordo com a NBC PG 01 – Código de Ética Profissional do Contador, o contador pode','{"A": "assinar documentos ou peças contábeis elaborados por outro profissional alheio à sua orientação, supervisão ou revisão.", "B": "transferir, parcialmente, a execução dos serviços a seu cargo a outro profissional, transferindo para este a responsabilidade técnica.", "C": "publicar, em seu nome, trabalho científico ou técnico do qual não tenha participado, mas que são úteis à comunidade contábil.", "D": "transferir o contrato de serviços a seu cargo a outro profissional, que achar mais capacitado, mesmo sem a anuência do cliente.", "E": "indicar, em qualquer modalidade ou veículo de comunicação, títulos, especializações, serviços oferecidos, trabalhos realizados e, quando autorizada, a relação de clientes."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',56,'Matemática Financeira',null,'A fim de antecipar fluxo de caixa, uma empresa comercial privada descontou uma duplicata de R$ 60.000,00 junto a uma instituição financeira. Nessa operação, após descontados os juros, o IOF devido e a taxa de administração de R$ 80,00, a empresa recebeu R$ 52.000,00 líquidos. A instituição financeira desconta duplicatas a juros simples de 1,8% ao mês. O IOF é cobrado por meio de duas alíquotas que incidem sobre o valor da duplicata: I. a primeira, fixada em 0,38%; II. a segunda, de 0,0041% ao dia. Considerando-se o mês comercial, conclui-se que a duplicata foi descontada com um prazo de antecedência','{"A": "menor do que 120 dias.", "B": "maior do que 120 dias e menor do que 150 dias.", "C": "maior do que 150 dias e menor do que 180 dias.", "D": "maior do que 180 dias e menor do que 210 dias.", "E": "maior do que 210 dias."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',57,'Matemática Financeira',null,'Um empréstimo foi concedido para ser quitado em 4 prestações mensais, iguais e consecutivas no valor de R$ 6.615,00, sendo a primeira delas paga um mês após a contratação do empréstimo. Entretanto, esse primeiro pagamento não foi efetuado na data prevista. Na data do pagamento da 2ª prestação, o devedor decide quitar toda a sua dívida, pagando os atrasados, a prestação vigente e trazendo os pagamentos futuros a valor presente. Os juros contratados são de 5% ao mês e o credor cobra, em caso de atraso, apenas multa moratória fixa de 2% sobre o valor atrasado. Para quitar a sua dívida, o devedor precisará pagar','{"A": "R$ 25.662,30.", "B": "R$ 25.860,75.", "C": "R$ 25.993,05.", "D": "R$ 26.000,00.", "E": "R$ 26.042,05."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',58,'Matemática Financeira',null,'Uma aplicação sofre capitalização composta diariamente. Após 60 dias, o rendimento dessa aplicação foi de 0,54% a.m. Considerando o mês comercial, a taxa mensal efetiva dessa operação foi','{"A": "1,0001830 – 1", "B": "1,0001860 – 1", "C": "1,0000930 – 1", "D": "1,0000960 – 1", "E": "0,0054"}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',59,'Matemática Financeira',null,'Um capital de R$ 32.400,00 é aplicado à taxa composta de 20% ao ano, durante dois anos e três meses. Se esse valor fosse submetido à convenção linear, o montante final seria, com relação ao montante obtido na aplicação original, [Dado: 1,202,25 = 1,507]','{"A": "R$ 1.620,00 maior.", "B": "R$ 324,00 menor.", "C": "R$ 324,00 maior.", "D": "R$ 162,00 menor.", "E": "R$ 162,00 maior."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',60,'Matemática Financeira',null,'Considere o seguinte fluxo de caixa de um projeto de investimento. Anos 0 1 2 3 4 R$ (230.000) P 64.480 P 74.880 Esse projeto apresenta Taxa Interna de Retorno de 20% ao ano. Os rendimentos esperados P ao final do primeiro e do terceiro anos de investimento são idênticos. O valor de P está entre','{"A": "R$ 104.000,00 e R$ 105.000,00.", "B": "R$ 105.000,00 e R$ 106.000,00.", "C": "R$ 106.000,00 e R$ 107.000,00.", "D": "R$ 107.000,00 e R$ 108.000,00.", "E": "R$ 108.000,00 e R$ 109.000,00."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno')
